                v[j] = x[r1] + rng.uniform(-1, 1) * (x[r2] - x[r1])
            else:
                mu = rng.uniform(lb, ub)
                v[j] = x[r1] + mu

        f_x = func(x)
        f_v = func(v)

        for j in range(pop_size):
